def find_largest_palindromic_cube(n: int) -> str:
    x = 1
    ans = str(x)

    while x**3 <= n:
        s = str(x**3)
        l = len(s)
        kai = True
        for i in range(l // 2):
            if s[i] != s[l - i - 1]:
                kai = False
                break
        if kai:
            ans = s
        x += 1
    return ans
